import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    k = list(map(int, data[1:1 + n]))
    total = sum(k)
    best = total
    for mask in range(1 << n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += k[i]
        m = max(s, total - s)
        if m < best:
            best = m
    print(best)

if __name__ == "__main__":
    main()
